public class METHashHelper
{
    private static const str AllValue = 'all';
    private static const str ColonChar = ':';
    private static const str SlashChar = '/';
    private static Map linkHashStringMaps = null;
    private static Map customerAttributes = null;
    private static Map salesTableAttributes = null;
    private static Map productAttributes = null;
    private static Map salesLineAttributes = null;
    private static boolean hasInitilized;
    private static Map ruleCache = new Map(Types::Int64, Types::Container);
    private static Map ruleExclusionCache = new Map(Types::Int64, Types::Container);
    private static Map ruleTableLineAttrConditionCache = new Map(Types::Int64, Types::Class);

}

