[SysObsolete('This method is not used anymore', false, 30\08\2023)]
public static str getMD5StringHash(str _string)
{
    str s;
    ClrObject obj, md5, clrStr, clrStrObject;
    System.Text.StringBuilder sBuilder;
    System.Exception clrException;
    System.Array resultByteArray;
    int i, arrayLength;
    InteropPermission perm;

    perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();
    try
    {
        obj = System.Text.Encoding::get_ASCII().GetBytes(_string);
        md5 = System.Security.Cryptography.MD5::Create();
        resultByteArray = md5.ComputeHash(obj);
        //BP deviation documented
        sBuilder = new System.Text.StringBuilder();
        arrayLength = resultByteArray.get_Length();
        // Loop through each byte of the hashed data
        // and format each one as a hexadecimal string.
        for (i = 0; i < arrayLength; i++)
        {
            clrStrObject = resultByteArray.GetValue(i);
            clrStr = clrStrObject.ToString('x2');
            sBuilder.Append(clrStr);
        }

        // Return the hexadecimal string.
        s = sBuilder.ToString();
    }
    catch (Exception::CLRError)
    {
        //BP deviation documented
        clrException = CLRInterop::getLastException();
        s = clrException.get_Message();
        error(s);
        throw error("@SYS106158");
    }

    CodeAccessPermission::revertAssert();
    return s;
}

internal static str HashValue(str _hashKey)
{
    //if (GUPHashThreadSafeFlight::instance().isEnabled())
    {
        str hashString;
        if (!_hashKey)
        {
            return hashString;
        }

        using (System.Security.Cryptography.SHA256 hasher = System.Security.Cryptography.SHA256::Create())
        {
            System.Byte[] hashKeyBytes = System.Text.Encoding::Default.GetBytes(_hashKey);
            System.Byte[] hash = hasher.ComputeHash(hashKeyBytes);
            hashString = strLwr(strRem(System.BitConverter::ToString(hash), '-'));
        }

        return hashString;
    }
    /*
    else
    {
        return HashFunctions::ComputeHashAsHexString(_hashKey, HashType::SHA256);
    }
    */
}

internal static str getAllValue()
{
    return allValue;
}

internal static str getColonChar()
{
    return ColonChar;
}

internal static str getSlashChar()
{
    return SlashChar;
}

internal static Set calculateHashValueForHashKeySet(Set hashKey)
{
    Set hashValue = new Set(Types::String);
    SetEnumerator setEnumerator = hashKey.getEnumerator();

    while (setEnumerator.moveNext())
    {
        hashValue.add(METHashHelper::HashValue(setEnumerator.current()));
    }

    return hashValue;
}

internal static Set calculateHashValueForHashKeySetFromCache(Set hashKey, Map _hashCache)
{
    Set hashValue = new Set(Types::String);
    SetEnumerator setEnumerator = hashKey.getEnumerator();

    while (setEnumerator.moveNext())
    {
        hashValue.add(METHashHelper::getHashValueFromCache(setEnumerator.current(), _hashCache));
    }

    return hashValue;
}

internal static str getHashValueFromCache(str _hashKey, Map _hashCache)
{
    str hashValue;
    if (_hashCache.exists(_hashKey))
    {
        hashValue = _hashCache.lookup(_hashKey);
    }
    else
    {
        hashValue = METHashHelper::HashValue(_hashKey);
        _hashCache.add(_hashKey, hashValue);
    }
    return hashValue;
}

internal static void updateHash(boolean _runDelta = false)
{
    ttsbegin;

    if (_runDelta)
    {
        METHashHelper::updateHashDelta();
    }
    else
    {
        METHashHelper::updateHashAll();
    }

    METHashHelper::insertHashForNonRule();

    ttscommit;
}

internal static void insertHashForNonRule()
{
    GUPRuleHash ruleHash;
    select RecId from ruleHash
        where ruleHash.RuleId == 0;

    if (!ruleHash.RecId)
    {
        ruleHash.RuleId = 0;
        ruleHash.HighestAttributePriority = 0;
        ruleHash.HashValue = METHashHelper::HashValue(allValue);
        ruleHash.insert();
    }
}

internal static void updateHashAll()
{
    GUPPricingRule pricingRule;
    RecordInsertList recordInsertList = new RecordInsertList(tableNum(GUPRuleHash));
    GUPRuleHash ruleHash;

    delete_from ruleHash;

    while select PriceAttributeGroupName, RecId from pricingRule
    {
        METHashHelper::insertRuleHash(pricingRule, recordInsertList);
    }

    recordInsertList.insertDatabase();
}

internal static void updateHashDelta()
{
    GUPPricingRule pricingRule;
    RecordInsertList recordInsertList = new RecordInsertList(tableNum(GUPRuleHash));
    GUPRuleHash ruleHash;

    while select PriceAttributeGroupName, RecId from pricingRule
        notexists join ruleHash
        where pricingRule.RecId == ruleHash.RuleId
    {
        METHashHelper::insertRuleHash(pricingRule, recordInsertList);
    }

    recordInsertList.insertDatabase();
}

internal static void insertRuleHash(GUPPricingRule _pricingRule, RecordInsertList _recordInsertList)
{
    GUPRuleHash ruleHash;
    ruleHash.clear();
    ruleHash.RuleId = _pricingRule.RecId;
    ruleHash.HasExclusion = GUPRuleHash::METRuleHasExclusion(_pricingRule.RecId);
    Set hashKey = GUPRuleHash::METGetHashKeySetForPricingRule(_pricingRule, ruleHash);
    SetEnumerator setEnumerator = hashKey.getEnumerator();

    while (setEnumerator.moveNext())
    {
        ruleHash.HashValue = METHashHelper::HashValue(setEnumerator.current());
        _recordInsertList.add(ruleHash);
    }
}

internal static List getPropertyValueListByAttribute(
    Common _pricingobject,
    GUPPricingAttributeLink _attrLink,
    Map _customerAttributeValues = null,
    Map _salesTableAttributeValues = null,
    Map _productAttributeValues = null,
    Map _salesLineAttributeValues = null,
    boolean _isPriceSimulator = false,
    boolean _isPriceReport = false,
    anytype _salesTransactionId = '')
{
    Map propertiesMap;
    Map attributesMap;
    str attrValue;
    List propertyValueList = new List(Types::String);
    str hashString = METHashHelper::getHashStringForAttributeLink(_attrLink);

    switch (_attrLink.Source)
    {
        case GUPPricingAttributeSource::Customer:
            propertiesMap = _customerAttributeValues;
            attributesMap = customerAttributes;
            break;
        case GUPPricingAttributeSource::SalesTable:
            propertiesMap = _salesTableAttributeValues;
            attributesMap = salesTableAttributes;
            break;
        case GUPPricingAttributeSource::Product:
            propertiesMap = _productAttributeValues;
            attributesMap = productAttributes;
            break;
        case GUPPricingAttributeSource::SalesLine:
            propertiesMap = _salesLineAttributeValues;
            attributesMap = salesLineAttributes;
            break;
    }

    if (!attributesMap.exists(hashString))
    {
        propertyValueList.addEnd(allValue);
        return propertyValueList;
    }

    GUPIPricingAttribute pricingAttribute = attributesMap.lookup(hashString);

    if (propertiesMap.exists(hashString))
    {
        attrValue = propertiesMap.lookup(hashString).ToString();

        if (attrValue != '')
        {
            if (_attrLink.Source == GUPPricingAttributeSource::SalesTable && (_isPriceSimulator || _isPriceReport))
            {
                propertyValueList = strSplit(attrValue, ',');
            }
            else
            {
                propertyValueList = _attrLink.METGetAttributeValueList(attrValue);
            }
        }

        propertyValueList = METHashHelper::removeUnusedZeroForList(pricingAttribute, propertyValueList);
        propertyValueList.addEnd(allValue);
        return propertyValueList;
    }

    if (_attrLink.Source == GUPPricingAttributeSource::SalesTable && (_isPriceSimulator || _isPriceReport))
    {
        if (_isPriceSimulator)
        {
            GUPPricingSimulatorHeaderAttributeCondation simulatorHeaderAttributeCondition;

            select firstonly Value from simulatorHeaderAttributeCondition
                where simulatorHeaderAttributeCondition.RetailPricingSimulatorSalesTransaction == any2Int64(_salesTransactionId)
                    && simulatorHeaderAttributeCondition.PriceAttributeClassId == _attrLink.PriceAttributeClassId
                    && simulatorHeaderAttributeCondition.ProviderClassId == _attrLink.AttributeProviderClassId
                    && simulatorHeaderAttributeCondition.TypeName == _attrLink.TypeName
                    && simulatorHeaderAttributeCondition.AttributeName == _attrLink.AttributeName;

            attrValue = simulatorHeaderAttributeCondition.Value;
        }
        else if (_isPriceReport)
        {
            GUPPricingReportHeaderAttributeCondition reportHeaderAttributeCondition;

            select firstonly Value from reportHeaderAttributeCondition
                where reportHeaderAttributeCondition.ReportId == _salesTransactionId
                    && reportHeaderAttributeCondition.PriceAttributeClassId == _attrLink.PriceAttributeClassId
                    && reportHeaderAttributeCondition.ProviderClassId == _attrLink.AttributeProviderClassId
                    && reportHeaderAttributeCondition.TypeName == _attrLink.TypeName
                    && reportHeaderAttributeCondition.AttributeName == _attrLink.AttributeName;

            attrValue = reportHeaderAttributeCondition.Value;
        }

        if (attrValue != '')
        {
            propertyValueList = strSplit(attrValue, ',');
        }
    }
    else
    {
        GUPIPricingAttribute attribute = attributesMap.lookup(hashString);
        attrValue = attribute.getValueOfAttribute(_pricingObject).ToString();
        if (attrValue != '')
        {
            propertyValueList = _attrLink.METGetAttributeValueList(attrValue);
        }
    }

    propertyValueList = METHashHelper::removeUnusedZeroForList(pricingAttribute, propertyValueList);
    propertiesMap.add(hashString, attrValue);
    propertyValueList.addEnd(allValue);
    return propertyValueList;
}

internal static List removeUnusedZeroForList(GUPIPricingAttribute _pricingAttribute, List _propertyValueList)
{
    if (_pricingAttribute.getDataType() == AttributeDataType::Decimal)
    {
        ListEnumerator listEnumerator = _propertyValueList.getEnumerator();
        List propertyValueList = new List(Types::String);

        while (listEnumerator.moveNext())
        {
            str attrValue = listEnumerator.current();
            attrValue = METHashHelper::removeUnusedZeroForStr(_pricingAttribute, attrValue);
            propertyValueList.addEnd(attrValue);
        }

        return propertyValueList;
    }
    else
    {
        return _propertyValueList;
    }
}

internal static str removeUnusedZeroForStr(GUPIPricingAttribute _pricingAttribute, str _attrValue)
{
    if (_pricingAttribute.getDataType() == AttributeDataType::Decimal
        && _attrValue != ''
        && _attrValue != AllValue)
    {
        _attrValue = System.String::Format("{0:G29}", str2Num(_attrValue));
    }

    return _attrValue;
}

internal static Set getPropertyHashKeySetForPricingObject(
    Common _pricingObject,
    GUPPricingAttributeSourceLevel _sourceLevel = GUPPricingAttributeSourceLevel::Header,
    Map _productAttributeValues = null,
    Map _salesLineAttributeValues = null,
    CustTable _custTable = null,
    boolean _isSalesQuotation = false,
    boolean _isPriceSimulator = false,
    boolean _isPriceReport = false,
    anytype _salesTransactionId = '')
{
    METHashHelper::initAttributesBySource();
    Map customerAttributeValues = new Map(Types::String, Types::AnyType);
    Map salesTableAttributeValues = new Map(Types::String, Types::AnyType);
    _productAttributeValues = _productAttributeValues ? _productAttributeValues : new Map(Types::String, Types::AnyType);
    _salesLineAttributeValues = _salesLineAttributeValues ? _salesLineAttributeValues : new Map(Types::String, Types::AnyType);

    GUPPricingAttributeLink attributeLink;
    GUPPricingAttributeGroup attributeGroup;
    Set hashKeySet = new Set(Types::String);
    Query attrGroupQuery = GUPHashHelper::getAttributeGroupQuery(_sourceLevel);
    QueryRun queryRun = new QueryRun(attrGroupQuery);

    while (queryRun.next())
    {
        attributeGroup = queryRun.get(tableNum(GUPPricingAttributeGroup));

        Set hashKeySetOneGroup = new Set(Types::String);

        while select AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId from attributeLink
            order by attributeLink.Priority
            where attributeLink.PriceAttributeGroupName == attributeGroup.Name
               && attributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
               && attributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup
        {
            List propertyValueList;

            if (attributeLink.Source == GUPPricingAttributeSource::Product)//TODO: maybe purchLine?
            {
                propertyValueList = METHashHelper::getPropertyValueListByAttribute(_pricingObject, attributeLink, customerAttributeValues, salesTableAttributeValues, _productAttributeValues, _salesLineAttributeValues, _isPriceSimulator, _isPriceReport, _salesTransactionId);
            }

            hashKeySetOneGroup = METHashHelper::refreshHashKeySetOneGroup(hashKeySetOneGroup, propertyValueList, attributeLink);
        }
        hashKeySet = Set::union(hashKeySet, hashKeySetOneGroup);
    }

    hashKeySet.add(strLRTrim(strLwr(allValue)));
    return hashKeySet;
}

internal static Set refreshHashKeySetOneGroup(
    Set _hashKeySetOneGroup,
    List _propertyValueList,
    GUPPricingAttributeLink _attributeLink)
{
    if (_hashKeySetOneGroup.empty())
    {
        ListEnumerator propertyValueEnum = _propertyValueList.getEnumerator();
        while (propertyValueEnum.moveNext())
        {
            _hashKeySetOneGroup.add(strLRTrim(strLwr(int642Str(_attributeLink.RecId) + ColonChar + strLRTrim(propertyValueEnum.current()))));
        }
    }
    else
    {
        Set newHashKeys = new Set(Types::String);
        SetEnumerator setEnumerator = _hashKeySetOneGroup.getEnumerator();
        while (setEnumerator.moveNext())
        {
            ListEnumerator propertyValueEnum = _propertyValueList.getEnumerator();
            while (propertyValueEnum.moveNext())
            {
                newHashKeys.add(strLRTrim(strLwr(setEnumerator.current())) + SlashChar + strLRTrim(strLwr(int642Str(_attributeLink.RecId) + ColonChar + strLRTrim(propertyValueEnum.current()))));
            }
        }
        _hashKeySetOneGroup = newHashKeys;
    }
    return _hashKeySetOneGroup;
}

private static Set getAllSetAttributeLink()
{
    GUPPricingRuleCondition ruleCondition;
    GUPPricingAttributeLink attrLink;
    Set validLinks = new Set(Types::String);

    while select PriceAttributeClassId, AttributeProviderClassId, AttributeName, TypeName, RecId from attrLink
        exists join ruleCondition
        where ruleCondition.ConditionAttribute == attrLink.RecId
           && ruleCondition.ConditionValue != ''
    {
        str hashString = METHashHelper::getHashStringForAttributeLink(attrLink);
        if (!validLinks.in(hashString))
        {
            validLinks.add(hashString);
        }
    }

    return validLinks;
}

private static str getHashStringForAttributeLink(GUPPricingAttributeLink _attrLink)
{
    if (!linkHashStringMaps)
    {
        linkHashStringMaps = new Map(Types::Int64, Types::String);
    }

    if (linkHashStringMaps.exists(_attrLink.RecId))
    {
        return linkHashStringMaps.lookup(_attrLink.RecId);
    }

    GUPIPricingAttribute priceAttribute = _attrLink.pricingAttribute();
    str hashString = priceAttribute.GetHashString();
    linkHashStringMaps.add(_attrLink.RecId, hashString);
    return hashString;
}

internal static boolean initAttributesBySource(boolean _checkValidLinks = true)
{
    if (!hasInitilized)
    {
        List pricingAttributes = GUPPricingAttributeRepository::getAllUsedPricingAttributes();
        Set validLinks = _checkValidLinks ? METHashHelper::getAllSetAttributeLink(): new Set(Types::String);
        ListEnumerator enum = pricingAttributes.getEnumerator();

        customerAttributes = new Map(Types::String, Types::Class);
        salesTableAttributes = new Map(Types::String, Types::Class);
        productAttributes = new Map(Types::String, Types::Class);
        salesLineAttributes = new Map(Types::String, Types::Class);

        while (enum.moveNext())
        {
            GUPAbstractPricingAttribute attribute = enum.current();
            str hashString = attribute.GetHashString();
            if (!_checkValidLinks || validLinks.in(hashString))
            {
                GUPPricingAttributeSource source = GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                attribute,
                attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmSource();

                switch (source)
                {
                    case GUPPricingAttributeSource::Customer:
                        customerAttributes.add(hashString, attribute);
                        break;
                    case GUPPricingAttributeSource::SalesTable:
                        salesTableAttributes.add(hashString, attribute);
                        break;
                    case GUPPricingAttributeSource::Product:
                        productAttributes.add(hashString, attribute);
                        break;
                    case GUPPricingAttributeSource::SalesLine:
                        salesLineAttributes.add(hashString, attribute);
                        break;
                }
            }
        }
        hasInitilized = true;
    }

    return hasInitilized;
}

internal static boolean parmHasInitilized(boolean _hasInitilized = hasInitilized)
{
    hasInitilized = _hasInitilized;
    return hasInitilized;
}

internal static boolean checkRuleMatchedWithHashSet(
    Set _hashSet,
    RecId _ruleId,
    Common _pricingObject)
{
    Set ruleHashSet;
    Set ruleExclusionSet;
    GUPPricingRuleExclusionType exclusionType;
    boolean hasExclusion = false;
    boolean ruleMatched = false;
    boolean exclusionMatched = false;

    if (_ruleId == 0)
    {
        return true;
    }

    if (!ruleCache.exists(_ruleId))
    {
        GUPRuleHash gupRuleHash;
        ruleHashSet = new Set(Types::String);
        ruleExclusionSet = new Set(Types::String);

        while select HashValue, HasExclusion from gupRuleHash
            where gupRuleHash.RuleId == _ruleId
        {
            ruleHashSet.add(gupRuleHash.HashValue);
            hasExclusion = gupRuleHash.HasExclusion;
        }

        if (hasExclusion)
        {
            GUPPricingRuleExclusion pricingRuleExclusion;
            GUPPricingRule pricingRule;

            while select Exclusion from pricingRuleExclusion
                where pricingRuleExclusion.RuleId == _ruleId
            {
                ruleExclusionSet.add(pricingRuleExclusion.Exclusion);
            }

            select firstonly ExclusionType from pricingRule where pricingRule.RecId == _ruleId;
            exclusionType = pricingRule.ExclusionType;
        }

        ruleCache.add(_ruleId, [ruleHashSet.pack(), hasExclusion, exclusionType, ruleExclusionSet.pack()]);
    }
    else
    {
        container ruleContainer = ruleCache.lookup(_ruleId);
        container packedRuleHashSet, packedRuleExclusionSet;
        [packedRuleHashSet, hasExclusion, exclusionType, packedRuleExclusionSet] = ruleContainer;
        ruleHashSet = Set::create(packedRuleHashSet);
        ruleExclusionSet = Set::create(packedRuleExclusionSet);
    }

    ruleMatched = Set::intersection(ruleHashSet, _hashSet).elements() > 0;

    if (ruleMatched && hasExclusion)
    {
        exclusionMatched = METHashHelper::checkExclusion(exclusionType, ruleExclusionSet, _pricingObject);
    }

    return ruleMatched && !exclusionMatched;
}

private static boolean checkExclusion(
    GUPPricingRuleExclusionType _exclusionType,
    Set _ruleExclusionSet,
    Common _pricingObject)
{
    boolean exclusionMatched = false;
    switch (_exclusionType)
    {
        case GUPPricingRuleExclusionType::Customer:
            exclusionMatched = _ruleExclusionSet.in(any2Str(_pricingObject.(fieldNum(SalesTable, custAccount))));
            break;
        case GUPPricingRuleExclusionType::Product:
            exclusionMatched = _ruleExclusionSet.in(any2Str(_pricingObject.(fieldNum(SalesLine, ItemId))));
            break;
        case GUPPricingRuleExclusionType::ProductVariant:
            RetailVariantId variantId = _pricingObject.(fieldNum(SalesLine,RetailVariantId));
            ItemId itemId = _pricingObject.(fieldNum(SalesLine, ItemId));
            if (variantId)
            {
                InventDim inventDim = InventDim::find(InventDimCombination::findVariantId(variantId).InventDimId);
                RefRecId distinctProductVariant = InventDimCombination::findByInventDim(itemId, inventDim).DistinctProductVariant;
                exclusionMatched = _ruleExclusionSet.in(any2Str(distinctProductVariant));
            }
            break;
    }
    return exclusionMatched;
}

internal static boolean checkRuleMatchedWithExclusion(
    RecId _ruleId,
    Common _pricingObject)
{
    if (_ruleId == 0)
    {
        return false;
    }

    Set ruleExclusionSet;
    GUPPricingRuleExclusionType exclusionType;
    boolean hasExclusion = false;
    boolean exclusionMatched = false;

    if (!ruleExclusionCache.exists(_ruleId))
    {
        GUPRuleHash gupRuleHash;
        ruleExclusionSet = new Set(Types::String);

        select firstonly HasExclusion from gupRuleHash where gupRuleHash.RuleId == _ruleId;
        hasExclusion = gupRuleHash.HasExclusion;

        if (hasExclusion)
        {
            GUPPricingRuleExclusion pricingRuleExclusion;
            GUPPricingRule pricingRule;

            while select Exclusion from pricingRuleExclusion
                where pricingRuleExclusion.RuleId == _ruleId
            {
                ruleExclusionSet.add(pricingRuleExclusion.Exclusion);
            }

            select firstonly ExclusionType from pricingRule where pricingRule.RecId == _ruleId;
            exclusionType = pricingRule.ExclusionType;
        }

        ruleExclusionCache.add(_ruleId, [hasExclusion, exclusionType, ruleExclusionSet.pack()]);
    }
    else
    {
        container ruleContainer = ruleExclusionCache.lookup(_ruleId);
        container packedRuleExclusionSet;
        [hasExclusion, exclusionType, packedRuleExclusionSet] = ruleContainer;
        ruleExclusionSet = Set::create(packedRuleExclusionSet);
    }

    if (hasExclusion)
    {
        exclusionMatched = METHashHelper::checkExclusion(exclusionType, ruleExclusionSet, _pricingObject);
    }

    return exclusionMatched;
}

internal static boolean checkRuleMatchedWithTableOrLineAttribute(
    RecId _ruleId,
    Common _pricingObject)
{
    if (_ruleId == 0)
    {
        return true;
    }

    Map ruleConditionMap;

    if (!ruleTableLineAttrConditionCache.exists(_ruleId))
    {
        ruleConditionMap = new Map(Types::Class, Types::String);

        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeLink attrLink;

        while select ConditionValue from ruleCondition
            where ruleCondition.ConditionValue != ''
               && ruleCondition.RuleId == _ruleId
            join AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId from attrLink
            where ruleCondition.ConditionAttribute == attrLink.RecId
               && (attrLink.Source == GUPPricingAttributeSource::SalesTable
               || attrLink.Source == GUPPricingAttributeSource::SalesLine)
        {
            GUPIPricingAttribute attribute = attrLink.pricingAttribute();
            ruleConditionMap.add(attribute, ruleCondition.ConditionValue);
        }
        ruleTableLineAttrConditionCache.add(_ruleId, ruleConditionMap);
    }
    else
    {
        ruleConditionMap = ruleTableLineAttrConditionCache.lookup(_ruleId);
    }

    MapEnumerator mapEnumerator = ruleConditionMap.getEnumerator();

    while (mapEnumerator.moveNext())
    {
        GUPIPricingAttribute attribute = mapEnumerator.currentKey();
        str attrValue = attribute.getValueOfAttribute(_pricingObject).ToString();
        str conditionValue = mapEnumerator.currentValue();
        if (attrValue != '')
        {
            GUPAbstractPricingAttribute abstractPricingAttribute;
            if (attribute is GUPAbstractPricingAttribute)
            {
                abstractPricingAttribute = attribute as GUPAbstractPricingAttribute;
            }

            if (abstractPricingAttribute && abstractPricingAttribute.isMultiValue())
            {
                boolean matched = false;
                ListEnumerator attrValuesListEnumerator = strSplit(attrValue, ',').getEnumerator();
                while (attrValuesListEnumerator.moveNext())
                {
                    if (METHashHelper::isAttribueValueMatchedWithRuleCondition(conditionValue, attribute, attrValuesListEnumerator.current()))
                    {
                        matched = true;
                        break;
                    }
                }

                if (!matched)
                {
                    return false;
                }
            }
            else
            {
                if (!METHashHelper::isAttribueValueMatchedWithRuleCondition(conditionValue, attribute, attrValue))
                {
                    return false;
                }
            }
        }
        else
        {
            return false;
        }
    }
    return true;
}

internal static boolean isAttribueValueMatchedWithRuleCondition(str _conditionValue, GUPIPricingAttribute _attribute, str _attrValue)
{
    ListEnumerator conditionValuesListEnumerator = strSplit(_conditionValue, ',').getEnumerator();
    boolean matched = false;
    while (conditionValuesListEnumerator.moveNext())
    {
        if (strCmp(strLwr(METHashHelper::removeUnusedZeroForStr(_attribute, conditionValuesListEnumerator.current())), strLwr(METHashHelper::removeUnusedZeroForStr(_attribute, _attrValue))) == 0)
        {
            matched = true;
            break;
        }
    }

    return matched;
}

public static Query getAttributeGroupQuery(GUPPricingAttributeSourceLevel _sourceLevel = GUPPricingAttributeSourceLevel::Header)
{
    Query attrGroupQuery = new Query();
    QueryBuildDataSource qbdsAttrGroup = attrGroupQuery.addDataSource(tableNum(GUPPricingAttributeGroup));
    qbdsAttrGroup.addRange(fieldNum(GUPPricingAttributeGroup, IsValid)).value(queryValue(NoYes::Yes));
    qbdsAttrGroup.addRange(fieldNum(GUPPricingAttributeGroup, SourceLevel)).value(queryValue(_sourceLevel));
    qbdsAttrGroup.addRange(fieldNum(GUPPricingAttributeGroup, GroupType)).value(queryValue(GUPPricingAttributeGroupType::General));
    qbdsAttrGroup.addSelectionField(fieldNum(GUPPricingAttributeGroup, Name));
    return attrGroupQuery;
}

